//! The Rust source of the generated tables.

use crate::model::{Attributes, Digitizer, Tablet};
use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::path::PathBuf;

const HEADER: &str = "\
// Generated by ntd-codegen from tablets/OpenTabletDriver. Do not edit.
// Regenerate with `cargo run --locked -p ntd-codegen`.
";

/// The files to write, as (name inside `generated/`, content).
pub(crate) fn files(tablets: &[(PathBuf, Tablet)]) -> Vec<(&'static str, String)> {
    vec![("mod.rs", module()), ("tablets.rs", tables(tablets))]
}

fn module() -> String {
    format!(
        "{HEADER}\
//! The tablet definitions of `OpenTabletDriver`, as static tables.

#![allow(clippy::unreadable_literal, reason = \"generated code\")]

mod tablets;

pub(crate) use tablets::{{BY_ID, TABLETS}};
"
    )
}

fn tables(tablets: &[(PathBuf, Tablet)]) -> String {
    let mut out = String::from(HEADER);
    out.push_str(
        "\nuse crate::descriptor::{DigitizerDescriptor, IdEntry, TabletDescriptor};\n\n\
         pub(crate) static TABLETS: &[TabletDescriptor] = &[\n",
    );
    let mut by_id: BTreeMap<(u16, u16), Vec<(usize, usize)>> = BTreeMap::new();
    for (t, (_, tablet)) in tablets.iter().enumerate() {
        tablet_source(&mut out, tablet);
        for (d, id) in tablet.digitizer_identifiers.iter().enumerate() {
            by_id
                .entry((id.vendor_id, id.product_id))
                .or_default()
                .push((t, d));
        }
    }
    out.push_str("];\n\n");
    out.push_str(
        "/// (`VendorID`, `ProductID`) to (index in `TABLETS`, index in its digitizers), sorted.\n\
         pub(crate) static BY_ID: &[IdEntry] = &[\n",
    );
    for ((vid, pid), entries) in &by_id {
        let list: Vec<String> = entries.iter().map(|(t, d)| format!("({t}, {d})")).collect();
        let _ = writeln!(out, "    (({vid}, {pid}), &[{}]),", list.join(", "));
    }
    out.push_str("];\n");
    out
}

fn tablet_source(out: &mut String, t: &Tablet) {
    let s = &t.specifications;
    let aux = s.auxiliary_buttons.as_ref().and_then(|a| a.button_count);
    let _ = writeln!(out, "    TabletDescriptor {{");
    let _ = writeln!(out, "        name: {:?},", t.name);
    let _ = writeln!(out, "        width: {:?},", s.digitizer.width as f32);
    let _ = writeln!(out, "        height: {:?},", s.digitizer.height as f32);
    let _ = writeln!(out, "        max_x: {:?},", s.digitizer.max_x as f32);
    let _ = writeln!(out, "        max_y: {:?},", s.digitizer.max_y as f32);
    let _ = writeln!(out, "        max_pressure: {},", s.pen.max_pressure);
    let _ = writeln!(
        out,
        "        pen_button_count: {},",
        option(s.pen.button_count)
    );
    let _ = writeln!(out, "        auxiliary_button_count: {},", option(aux));
    attributes(out, 8, t.attributes.as_ref());
    let _ = writeln!(out, "        digitizers: &[");
    for id in &t.digitizer_identifiers {
        digitizer_source(out, id);
    }
    let _ = writeln!(out, "        ],");
    let _ = writeln!(out, "    }},");
}

fn digitizer_source(out: &mut String, d: &Digitizer) {
    let strings: Vec<String> = d
        .device_strings
        .iter()
        .flatten()
        .map(|(index, pattern)| format!("({index}, {pattern:?})"))
        .collect();
    let _ = writeln!(out, "            DigitizerDescriptor {{");
    let _ = writeln!(out, "                vendor_id: {},", d.vendor_id);
    let _ = writeln!(out, "                product_id: {},", d.product_id);
    let _ = writeln!(
        out,
        "                input_report_length: {},",
        option(d.input_report_length)
    );
    let _ = writeln!(
        out,
        "                output_report_length: {},",
        option(d.output_report_length)
    );
    let _ = writeln!(
        out,
        "                device_strings: &[{}],",
        strings.join(", ")
    );
    let _ = writeln!(out, "                report_parser: {:?},", d.report_parser);
    let _ = writeln!(
        out,
        "                output_init_report: {},",
        reports(d.output_init_report.as_ref())
    );
    let _ = writeln!(
        out,
        "                feature_init_report: {},",
        reports(d.feature_init_report.as_ref())
    );
    attributes(out, 16, d.attributes.as_ref());
    let _ = writeln!(out, "            }},");
}

/// `has_attributes` keeps the `{}` of the JSON apart from a missing object.
fn attributes(out: &mut String, indent: usize, a: Option<&Attributes>) {
    let pad = " ".repeat(indent);
    let text =
        |v: Option<&String>| v.map_or_else(|| "None".to_string(), |v| format!("Some({v:?})"));
    let _ = writeln!(out, "{pad}has_attributes: {},", a.is_some());
    let _ = writeln!(
        out,
        "{pad}interface: {},",
        text(a.and_then(|a| a.interface.as_ref()))
    );
    let _ = writeln!(
        out,
        "{pad}libinputoverride: {},",
        text(a.and_then(|a| a.libinputoverride.as_ref()))
    );
}

fn option<T: std::fmt::Display>(v: Option<T>) -> String {
    v.map_or_else(|| "None".to_string(), |v| format!("Some({v})"))
}

fn reports(v: Option<&Vec<String>>) -> String {
    v.map_or_else(
        || "None".to_string(),
        |list| {
            let items: Vec<String> = list.iter().map(|r| format!("{r:?}")).collect();
            format!("Some(&[{}])", items.join(", "))
        },
    )
}
